 public static class TeamsMail111HttpVerification {
  [Serializable] sealed class Connection {public string runId,origin;public int pid;public long clock;public bool actualBackend,replayEnabled,providersEnabled,productionEnabled;}
  [Serializable] sealed class Control {public string capacityPlayer="",capacityTag="",dropClaimCommand="",seedPlayer="",seedTeam="";public int capacityLives=-1;}
  [Serializable] sealed class Bindings {public string recipient,other,team,messageId,secondId;}
  [Serializable] sealed class Report {
   public string status="RUNNING",utc,unity;
   public string scope="Actual Unity managed guest/device signatures, authenticated social HTTP, protected pending reconstruction and authoritative wallet reads against an owned loopback real backend/SQLite. Fixed clock, private trusted-source mail issuance and one negative ledger capacity setup are explicit fixtures; one real committed reply is suppressed with503. No ordinary profile import, Android/device, live hosting/provider, natural cooldown, gameplay or production acceptance.";
   public int checks,cases,managedGuests,signedRequests,socialRequests,walletReads,protectedReconstructionCount;
   public bool actualHttp=true,ordinaryProfilesPreserved,serverReviewPreserved,settingsPreserved,languagePreferencePreserved;
   public List<int> signedStatuses=new List<int>(),socialStatuses=new List<int>();public List<string> passed=new List<string>(),errors=new List<string>();
  }
  static Report report;static Connection connection;static string temporary,vaultRoot,output,profiles,server,settings;static bool hadLanguage;static int language;
  static readonly Stack<IEnumerator> stack=new Stack<IEnumerator>();static readonly Queue<IEnumerator> dispatched=new Queue<IEnumerator>();static readonly List<IDisposable> cleanup=new List<IDisposable>();static readonly List<SocialBackendClient82> clients=new List<SocialBackendClient82>();static readonly List<IdentityHttpTransport82> identities=new List<IdentityHttpTransport82>();static AsyncOperation waiting;static double deadline;static bool finished;
  static string Id()=>Guid.NewGuid().ToString("N");
  static void Check(bool valid,string label){report.checks++;if(!valid)throw new InvalidOperationException(label);}
  static void Passed(string label){report.cases++;report.passed.Add(label);}
  static void Dispatch(IEnumerator value){dispatched.Enqueue(value);}
  static string Digest(string path){if(!Directory.Exists(path))return "Absent";return IdentityProtocol82.Sha(string.Join("\n",Directory.GetFiles(path,"*",SearchOption.AllDirectories).OrderBy(v=>v,StringComparer.Ordinal).Select(p=>p.Substring(path.Length)+":"+IdentityProtocol82.Sha(File.ReadAllBytes(p)))));}
  static IEnumerator Call<T>(Action<Action<SocialReply82<T>>> call,Action<T> assertion)where T:class{SocialReply82<T> reply=null;call(x=>reply=x);while(reply==null)yield return null;Check(reply.Succeeded,"Real typed social response succeeds");assertion?.Invoke(reply.value);}
  static ManagedIdentitySession82 Manager(EditorEphemeralIdentity82 vault,string path){var transport=new IdentityHttpTransport82(connection.origin,Dispatch,true);identities.Add(transport);cleanup.Add(transport);var manager=new ManagedIdentitySession82(vault.CreateKey(),vault.CreateStore(path),transport);cleanup.Add(manager);return manager;}
  static SocialBackendClient82 Client(ManagedIdentitySession82 owner,EditorEphemeralIdentity82 vault,string path){var store=vault.CreateStore(path);cleanup.Add(store);var client=new SocialBackendClient82(connection.origin,()=>owner.HasAccess?new SocialAccess82(owner.View.playerId,owner.AccessToken):null,Dispatch,store,true,true);clients.Add(client);cleanup.Add(client);return client;}
  static IEnumerator Guest(ManagedIdentitySession82 owner){IdentityReply82<IdentityView82> reply=null;owner.CreateGuest(Id(),x=>reply=x);while(reply==null)yield return null;Check(reply.Succeeded&&owner.HasAccess&&owner.View.hasSession,"Real managed guest enrollment succeeds with signed device challenge");report.managedGuests++;}
  static IEnumerator Wallet(ManagedIdentitySession82 owner,int expected,int coins=1250,Action<RuStoreServerWallet> extra=null){var wallet=new RuStoreBackendClient(connection.origin,owner.AccessToken,owner.View.playerId,true,true,Dispatch);cleanup.Add(wallet);PayReply<RuStoreServerWallet> reply=null;wallet.GetWallet(x=>reply=x);while(reply==null)yield return null;report.walletReads++;Check(reply.Succeeded&&reply.value.coins==coins&&reply.value.lives==expected&&!reply.value.localProfileMutated&&!reply.value.normalUnityProfileIntegrated,"Authoritative wallet fetch has expected lives and unchanged coins/local-profile isolation");extra?.Invoke(reply.value);}
  static void Operate(string player,int lives,string tag,string drop="",string seedPlayer="",string seedTeam=""){var value=new Control{capacityPlayer=player??"",capacityLives=lives,capacityTag=tag??"",dropClaimCommand=drop,seedPlayer=seedPlayer,seedTeam=seedTeam};File.WriteAllText(Path.Combine(temporary,"operator.json"),JsonUtility.ToJson(value),new UTF8Encoding(false));}
  static IEnumerator Flow(){
   var vaults=new EditorEphemeralIdentity82[2];var owners=new ManagedIdentitySession82[2];var social=new SocialBackendClient82[2];
   for(int n=0;n<2;n++){vaults[n]=new EditorEphemeralIdentity82();cleanup.Add(vaults[n]);owners[n]=Manager(vaults[n],Path.Combine(vaultRoot,"identity_"+n+".sealed"));yield return Guest(owners[n]);social[n]=Client(owners[n],vaults[n],Path.Combine(vaultRoot,"social_"+n+".sealed"));yield return Wallet(owners[n],5);}
   Check(owners[0].View.playerId!=owners[1].View.playerId,"Two actual managed internal players distinct");
   string team=null;yield return Call<SocialMutation82>(done=>social[0].CreateTeam(Id(),"Rain Mail111","Controlled loopback verification","drop",done),row=>team=row.teamId);
   yield return Call<SocialMutation82>(done=>social[1].JoinTeam(Id(),team,done),row=>Check(row.teamId==team&&row.state=="Joined","Second test player joins real team"));
   Operate(null,-1,null,"",owners[0].View.playerId,team);SocialMailList111 list=null;yield return Call<SocialMailList111>(done=>social[0].GetTeamMail111(team,0,done),row=>list=row);
   Check(list.messages.Length==3&&list.unreadCount==3,"Private trusted fixture produces three unread recipient-owned mails");
   var reward=list.messages.Single(v=>v.rewardCoins==300&&v.rewardLives==2);var later=list.messages.Single(v=>v.rewardCoins==100);Check(reward.claimState=="CapacityBlocked"&&!reward.canClaim,"Full wallet blocks full reward bundle");
   var binding=new Bindings{recipient=owners[0].View.playerId,other=owners[1].View.playerId,team=team,messageId=reward.messageId,secondId=later.messageId};File.WriteAllText(Path.Combine(temporary,"ExpectedBindings.json"),JsonUtility.ToJson(binding,true),new UTF8Encoding(false));
   yield return Call<SocialMailList111>(done=>social[1].GetTeamMail111(team,0,done),row=>Check(row.messages.Length==0&&row.unreadCount==0,"Team peer cannot see recipient-owned messages"));
   yield return Call<SocialMailDetail111>(done=>social[0].GetTeamMailDetail111(team,reward.messageId,done),row=>Check(row.message.readAtUtc==0,"Opening detail has not implicitly claimed or marked read"));
   string read=Id();SocialMutation82 readReceipt=null;yield return Call<SocialMutation82>(done=>social[0].ReadTeamMail111(read,team,reward.messageId,done),row=>readReceipt=row);
   yield return Call<SocialMutation82>(done=>social[0].ReadTeamMail111(read,team,reward.messageId,done),row=>Check(JsonUtility.ToJson(row)==JsonUtility.ToJson(readReceipt),"Exact read retry returns same receipt"));
   yield return Call<SocialMailList111>(done=>social[0].GetTeamMail111(team,0,done),row=>Check(row.unreadCount==2&&row.messages.Single(v=>v.messageId==reward.messageId).readAtUtc>0,"Server unread reconciles independently of reward"));
   string blockedId=Id();SocialMutation82 blocked=null;yield return Call<SocialMutation82>(done=>social[0].ClaimTeamMail111(blockedId,team,reward.messageId,done),row=>{blocked=row;Check(row.state=="CapacityBlocked"&&row.coins==1250&&row.lives==5,"Blocked full-wallet claim grants neither item");});yield return Wallet(owners[0],5);
   Operate(binding.recipient,3,"mail_room_two");yield return Wallet(owners[0],3);
   yield return Call<SocialMutation82>(done=>social[0].ClaimTeamMail111(blockedId,team,reward.messageId,done),row=>Check(JsonUtility.ToJson(row)==JsonUtility.ToJson(blocked),"Exact blocked retry remains old receipt after capacity change"));yield return Wallet(owners[0],3);
   string command=Id();Operate(null,-1,null,command);SocialReply82<SocialMutation82> lost=null;social[0].ClaimTeamMail111(command,team,reward.messageId,x=>lost=x);while(lost==null)yield return null;
   Check(!lost.Succeeded&&lost.unknown&&social[0].PendingCommand?.commandId==command,"Actual after-commit loss preserves claim intent");string oldBody=social[0].PendingCommand.body;
   social[0].Dispose();social[0]=Client(owners[0],vaults[0],Path.Combine(vaultRoot,"social_0.sealed"));report.protectedReconstructionCount++;Check(social[0].PendingCommand?.body==oldBody,"Fresh protected client recovers same intent");
   SocialMutation82 claimed=null;yield return Call<SocialMutation82>(done=>social[0].ResumePending(done),row=>{claimed=row;Check(row.state=="Claimed"&&row.rewardCoins==300&&row.rewardLives==2,"Same exact claim recovers real reward receipt");});yield return Wallet(owners[0],5,1550);
   yield return Call<SocialMutation82>(done=>social[0].ClaimTeamMail111(command,team,reward.messageId,done),row=>Check(JsonUtility.ToJson(row)==JsonUtility.ToJson(claimed),"Exact claimed retry returns same receipt"));yield return Wallet(owners[0],5,1550);
   yield return Call<SocialMutation82>(done=>social[0].ManageMember("transfer",Id(),team,owners[1].View.playerId,done),row=>Check(row.action=="transfer","Owner transfers leadership"));yield return Call<SocialMutation82>(done=>social[0].LeaveTeam(Id(),team,done),row=>Check(row.state=="Left","Recipient leaves team"));
   yield return Call<SocialOwnedMail111>(done=>social[0].GetOwnedMail111(0,done),row=>Check(row.rewards.Any(v=>v.messageId==later.messageId),"Owner can recover outstanding entitlement after leaving"));
   string final=Id();yield return Call<SocialMutation82>(done=>social[0].ClaimOwnedMail111(final,later.messageId,done),row=>Check(row.state=="Claimed"&&row.rewardCoins==100,"Owner collects outstanding mail after team leave"));yield return Call<SocialMutation82>(done=>social[0].ClaimOwnedMail111(final,later.messageId,done),row=>Check(row.state=="Claimed","Owned exact retry returns claimed receipt"));yield return Wallet(owners[0],5,1650);yield return Wallet(owners[1],5);Passed("Authenticated real mail read, blocked, lost-reply recovery and owner reward after leaving");
  }
  public static void Run(){
   output=Path.GetFullPath(Environment.GetEnvironmentVariable("HOTR_REVIEW111_HTTP_OUT")??throw new InvalidOperationException("Explicit111output required"));temporary=Path.GetFullPath(Environment.GetEnvironmentVariable("HOTR_REVIEW111_HTTP_PRIVATE")??throw new InvalidOperationException("Explicit private111 fixture required"));CheckPath();report=new Report{unity=Application.unityVersion};connection=JsonUtility.FromJson<Connection>(File.ReadAllText(Path.Combine(temporary,"connection.json")));var uri=new Uri(connection.origin);Check(uri.Scheme=="http"&&uri.Host=="127.0.0.1"&&uri.Port>0&&connection.actualBackend&&!connection.replayEnabled&&!connection.providersEnabled&&!connection.productionEnabled,"Exact owned loopback actual service is required");if(!System.Text.RegularExpressions.Regex.IsMatch(connection.runId??"","\\A[a-f0-9]{32}\\z"))throw new InvalidOperationException("ExactRunIdRequired111");vaultRoot=Path.GetFullPath("../.verification-cache/Launch82/TeamMail111/"+connection.runId);if(Directory.Exists(vaultRoot))throw new InvalidOperationException("FreshIgnoredVaultFixtureRequired111");Directory.CreateDirectory(vaultRoot);profiles=Digest(Path.Combine(Application.persistentDataPath,"Profiles"));server=Digest(Path.Combine(Application.persistentDataPath,"ServerReview"));settings=Digest("ProjectSettings");hadLanguage=PlayerPrefs.HasKey(GameLocale.PreferenceKey);language=PlayerPrefs.GetInt(GameLocale.PreferenceKey,-1);deadline=EditorApplication.timeSinceStartup+300;stack.Push(Flow());EditorApplication.update+=Tick;
  }
  static void CheckPath(){string root=Path.GetFullPath("../.verification-cache/Review111/MailHTTP")+Path.DirectorySeparatorChar;if(!temporary.StartsWith(root,StringComparison.OrdinalIgnoreCase)||!File.Exists(Path.Combine(temporary,"connection.json")))throw new InvalidOperationException("Fresh111privatefixture required");}
  static void Tick(){try{if(EditorApplication.timeSinceStartup>deadline)throw new TimeoutException("Bounded Help111actual HTTP suite timed out");if(waiting!=null){if(!waiting.isDone)return;waiting=null;}if(stack.Count==0){Finish();return;}var top=stack.Peek();if(!top.MoveNext()){stack.Pop();(top as IDisposable)?.Dispose();}else if(top.Current is IEnumerator child)stack.Push(child);else if(top.Current is AsyncOperation operation)waiting=operation;while(dispatched.Count>0)stack.Push(dispatched.Dequeue());}catch(Exception error){report.errors.Add(error.GetType().Name+": "+error.Message);Finish();}}
  static void Finish(){if(finished)return;finished=true;EditorApplication.update-=Tick;while(stack.Count>0)(stack.Pop()as IDisposable)?.Dispose();while(dispatched.Count>0)(dispatched.Dequeue()as IDisposable)?.Dispose();foreach(var client in clients){report.socialRequests+=client.VerificationRequests;report.socialStatuses.AddRange(client.VerificationStatuses);}foreach(var identity in identities){report.signedRequests+=identity.VerificationRequestCount;report.signedStatuses.AddRange(identity.VerificationStatuses);}for(int n=cleanup.Count-1;n>=0;n--)try{cleanup[n].Dispose();}catch(Exception){report.errors.Add("Owned HTTP cleanup failed");}try{report.ordinaryProfilesPreserved=profiles==Digest(Path.Combine(Application.persistentDataPath,"Profiles"));report.serverReviewPreserved=server==Digest(Path.Combine(Application.persistentDataPath,"ServerReview"));report.settingsPreserved=settings==Digest("ProjectSettings");report.languagePreferencePreserved=hadLanguage==PlayerPrefs.HasKey(GameLocale.PreferenceKey)&&language==PlayerPrefs.GetInt(GameLocale.PreferenceKey,-1);Check(report.ordinaryProfilesPreserved&&report.serverReviewPreserved&&report.settingsPreserved&&report.languagePreferencePreserved,"Ordinary data/settings/language remain byte-identical");}catch(Exception){report.errors.Add("Preservation audit failed");}report.utc=DateTime.UtcNow.ToString("o");report.status=report.errors.Count==0?"PASS_NATIVE_TEAMS_MAIL111_HTTP":"FAIL_NATIVE_TEAMS_MAIL111_HTTP";Directory.CreateDirectory(Path.Combine(output,"Native"));File.WriteAllText(Path.Combine(output,"Native","TeamsMail111_HTTP.json"),JsonUtility.ToJson(report,true),new UTF8Encoding(false));EditorApplication.Exit(report.errors.Count==0?0:1);}
 }
